/**
 * Compact opening book, generated by `scripts/build-openings.ts` from the lichess
 * chess-openings dataset (CC0) and served as a static file fetched on demand.
 *
 * The dataset lists named lines only: it has no game counts or results, so the book
 * carries none. `m` counts how many named lines of the dataset continue with a move,
 * which says how much theory follows it, not how often it is played.
 */
export interface OpeningBookFile {
  format: 1;
  source: string;
  license: string;
  /** [eco, name, moves in SAN separated by spaces]. */
  openings: [string, string, string][];
  /** Keyed by `positionKey(fen)`. */
  positions: Record<string, BookPositionEntry>;
}

export interface BookPositionEntry {
  /** Indexes into `openings` of the lines ending exactly at this position. */
  o?: number[];
  /** Theoretical continuations: [san, number of named lines through this move]. */
  m?: [string, number][];
}

export const OPENING_BOOK_URL = "/data/openings-v1.json";
